/** TV-native settings, private album, and explicitly opened local receiver. */
public final class WallpaperActivity extends Activity {
 private static WallpaperActivity current;
 private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-photo-library"));
 private SharedPreferences prefs;private WallpaperStore store;private LinearLayout list;private TextView status;
 private String page="main",photoId="",album="",receiverUrl="";private int albumOffset;private int generation;private boolean foreground;
 private Bitmap preview;private ImageView previewView;private PhotoReceiver receiver;private WallpaperOnline online;private ConnectivityManager.NetworkCallback networkCallback;
 private final Runnable expire=()->stopReceiver("Sesión caducada. Abre otra recepción para generar un QR nuevo.");
 public void onCreate(Bundle state){super.onCreate(state);current=this;prefs=getSharedPreferences("panel",0);store=new WallpaperStore(this);worker.allowCoreThreadTimeOut(true);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);}
 protected void onResume(){super.onResume();foreground=true;if(page.equals("receive"))page="main";render();}
 protected void onPause(){foreground=false;generation++;ui.removeCallbacks(expire);stopReceiver("");if(online!=null)online.cancel();releasePreview();super.onPause();}
 protected void onDestroy(){if(current==this)current=null;worker.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
 public void onTrimMemory(int level){super.onTrimMemory(level);if(level>=TRIM_MEMORY_RUNNING_LOW)releasePreview();}
 private void releasePreview(){if(previewView!=null){previewView.setImageDrawable(null);previewView=null;}if(preview!=null){preview.recycle();preview=null;}}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private void base(String title){generation++;releasePreview();ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xFF121722);list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(35),dp(22),dp(35),dp(22));scroll.addView(list);setContentView(scroll);TextView heading=new TextView(this);heading.setText(title);heading.setTextSize(23);heading.setTextColor(Color.WHITE);list.addView(heading);status=note("");}
 private TextView note(String text){TextView t=new TextView(this);t.setText(text);t.setTextColor(0xFFB8BFC7);t.setTextSize(14);t.setPadding(0,dp(6),0,dp(10));list.addView(t);return t;}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(Color.WHITE);b.setFocusable(true);android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();android.graphics.drawable.GradientDrawable selected=new android.graphics.drawable.GradientDrawable();selected.setColor(0xFF354955);selected.setCornerRadius(dp(5));selected.setStroke(dp(2),0xFFC4D0D7);android.graphics.drawable.GradientDrawable normal=new android.graphics.drawable.GradientDrawable();normal.setColor(0xFF222E38);normal.setCornerRadius(dp(5));states.addState(new int[]{android.R.attr.state_focused},selected);states.addState(new int[]{},normal);b.setBackground(states);b.setPadding(dp(14),dp(6),dp(14),dp(6));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(45));lp.bottomMargin=dp(7);list.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 private void message(String text){if(status!=null)status.setText(text);}
 private void task(Runnable action){try{worker.execute(action);}catch(RejectedExecutionException busy){message("Espera a que termine la operación actual");}}
 private void render(){if(!foreground)return;if(page.equals("library"))library();else if(page.equals("photo"))photo();else if(page.equals("albums"))albums();else main();}
 private void main(){page="main";base("Fondos del inicio");note("Solo se muestran en el inicio. No cambian el video ni el panel superpuesto.");String mode=prefs.getString("wallpaper_mode","original");
  button((mode.equals("original")?"✓ ":"")+"Actual — sin imágenes ni descargas",()->applyMode("original"));
  button((mode.equals("photo")?"✓ ":"")+"Una foto — elegir en mi biblioteca",()->{page="library";render();});
  button((mode.equals("slideshow")?"✓ ":"")+"Mis fotos — presentación automática",()->applyMode("slideshow"));
  button((mode.equals("daily")?"✓ ":"")+"Paisaje del día — Wikimedia",()->applyMode("daily"));
  button("Mi biblioteca: importar, ordenar y quitar",()->{page="library";render();});
  button("Recibir del celular · QR por Wi-Fi",this::receive);
  button("Elegir imágenes del TV o USB",this::chooseFiles);
  button("Calidad: "+(prefs.getString("wallpaper_quality","light").equals("light")?"Ligera · hasta 720p":"Equilibrada · hasta 1080p"),()->{String q=prefs.getString("wallpaper_quality","light").equals("light")?"balanced":"light";prefs.edit().putString("wallpaper_quality",q).apply();main();});
  button("Cambiar foto cada "+prefs.getInt("wallpaper_minutes",30)+" minutos",()->{int[] values={5,15,30,60};int value=prefs.getInt("wallpaper_minutes",30),next=30;for(int i=0;i<values.length;i++)if(values[i]==value)next=values[(i+1)%values.length];prefs.edit().putInt("wallpaper_minutes",next).apply();main();});
  if(mode.equals("daily")){button("Actualizar paisaje ahora",this::updateDaily);button("Información del fondo",this::credits);}
  button("Volver",this::finish);
 }
 private void applyMode(String mode){if(mode.equals("slideshow")){int token=generation;task(()->{boolean empty=store.photos().isEmpty();ui.post(()->{if(!foreground||token!=generation)return;if(empty){page="library";library();message("Importa al menos una imagen para la presentación");}else{prefs.edit().putString("wallpaper_mode",mode).apply();main();message("Presentación activada. Solo cambia mientras se ve el inicio.");}});});return;}prefs.edit().putString("wallpaper_mode",mode).apply();main();message(mode.equals("daily")?"Se descargará al volver al inicio; conservará el último paisaje sin Internet":"Fondo actual seleccionado");}
 private void library(){page="library";base("Mi biblioteca");note("Copias optimizadas de Z6 · máximo 50 imágenes / 100 MB. Quitar una copia no borra el original.");button("Recibir del celular",this::receive);button("Importar del TV o USB",this::chooseFiles);final int token=generation;task(()->{try{List<WallpaperStore.Photo> photos=store.photos();ui.post(()->{if(!foreground||token!=generation)return;if(photos.isEmpty())note("Tu biblioteca está vacía. Importa fotos para elegir un fondo.");for(WallpaperStore.Photo photo:photos)button(photo.name,()->{photoId=photo.id;page="photo";render();});button("Volver",()->{page="main";render();});});}catch(Exception e){ui.post(()->message(e.getMessage()));}});}
 private void photo(){page="photo";base("Vista previa");final int token=generation;task(()->{try{WallpaperStore.Photo p=store.find(photoId);if(p==null)throw new IOException("Imagen no disponible");Bitmap b=WallpaperStore.decode(p.file,Math.min(960,getResources().getDisplayMetrics().widthPixels),540);ui.post(()->{if(!foreground||token!=generation){b.recycle();return;}preview=b;ImageView view=new ImageView(this);previewView=view;view.setImageBitmap(b);view.setScaleType(ImageView.ScaleType.CENTER_CROP);int previewWidth=Math.min(dp(480),getResources().getDisplayMetrics().widthPixels-dp(70));LinearLayout.LayoutParams previewParams=new LinearLayout.LayoutParams(previewWidth,previewWidth*9/16);previewParams.gravity=Gravity.CENTER_HORIZONTAL;list.addView(view,previewParams);note(p.name+" · Se centra para llenar la pantalla");button("Usar esta foto",()->{prefs.edit().putString("wallpaper_photo",p.id).putString("wallpaper_mode","photo").apply();page="main";render();message("Foto seleccionada para el inicio");});button("Mover antes en la presentación",()->move(-1));button("Mover después en la presentación",()->move(1));button("Quitar de la biblioteca",()->new AlertDialog.Builder(this).setTitle("¿Quitar esta copia?").setMessage("El archivo original no se eliminará.").setPositiveButton("Quitar",(d,w)->task(()->{try{store.remove(photoId);ui.post(()->{page="library";render();});}catch(Exception e){ui.post(()->message(e.getMessage()));}})).setNegativeButton("Cancelar",null).show());button("Volver",()->{page="library";render();});});}catch(Exception e){ui.post(()->{if(foreground&&token==generation){message(e.getMessage());button("Volver",()->{page="library";render();});}});}});}
 private void move(int delta){task(()->{try{store.move(photoId,delta);ui.post(()->message("Orden guardado"));}catch(Exception e){ui.post(()->message(e.getMessage()));}});}
 private void chooseFiles(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);ResolveInfo result=getPackageManager().resolveActivity(intent,0);if(result!=null&&!result.activityInfo.packageName.equals("com.android.tv.frameworkpackagestubs")){try{startActivityForResult(intent,41);return;}catch(RuntimeException ignored){}}page="albums";albums();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=41||result!=RESULT_OK||data==null)return;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<Math.min(50,data.getClipData().getItemCount());i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());page="library";task(()->{int ok=0;String failure="";for(Uri uri:uris){File temp=null;try{temp=store.copyUri(uri);store.importImage(temp,displayName(uri));ok++;}catch(Exception e){failure=e.getMessage();}finally{if(temp!=null)temp.delete();}}final String text="Importadas: "+ok+(failure.isEmpty()?"":" · "+failure);ui.post(()->{render();message(text);});});}
 private String displayName(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "Imagen";}
 private void albums(){page="albums";base(album.isEmpty()?"Imágenes del TV y USB":album);note("Carpetas con imágenes que Android permite consultar. Si el USB no aparece, copia sus fotos a Imágenes o usa Recibir del celular.");if(checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){button("Permitir consultar imágenes",()->requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE},42));button("Recibir del celular",this::receive);button("Volver",()->{page="main";render();});return;}
  final int token=generation;final String selectedAlbum=album;task(()->{ArrayList<String[]> items=new ArrayList<>();String failure="";try{Set<String> volumes=MediaStore.getExternalVolumeNames(this);for(String volume:volumes){Uri collection=MediaStore.Images.Media.getContentUri(volume);int volumeCount=0;try(Cursor cursor=getContentResolver().query(collection,new String[]{MediaStore.Images.Media._ID,MediaStore.Images.Media.DISPLAY_NAME,MediaStore.Images.Media.RELATIVE_PATH},null,null,MediaStore.Images.Media.DISPLAY_NAME+" ASC")){while(cursor!=null&&cursor.moveToNext()&&volumeCount++<500){String folder=cursor.getString(2);items.add(new String[]{volume+" · "+(folder==null?"Imágenes":folder),cursor.getString(1),ContentUris.withAppendedId(collection,cursor.getLong(0)).toString()});}}}}catch(Exception e){failure="Android no permite consultar estas imágenes";}final String error=failure;ui.post(()->{if(!foreground||token!=generation)return;if(!error.isEmpty())message(error);if(items.isEmpty())note("No hay imágenes disponibles. Copia fotos a Imágenes del TV o recíbelas desde el celular.");ArrayList<String[]> choices=new ArrayList<>();if(selectedAlbum.isEmpty()){Set<String> folders=new LinkedHashSet<>();for(String[] item:items)folders.add(item[0]);for(String folder:folders)choices.add(new String[]{folder,"",""});}else for(String[] item:items)if(item[0].equals(selectedAlbum))choices.add(item);int from=Math.min(albumOffset,Math.max(0,choices.size()-1)),to=Math.min(from+50,choices.size());for(int i=from;i<to;i++){final String[] item=choices.get(i);if(selectedAlbum.isEmpty())button(item[0],()->{album=item[0];albumOffset=0;albums();});else button("Importar: "+item[1],()->importOne(Uri.parse(item[2]),item[1]));}if(from>0)button("Anteriores",()->{albumOffset=Math.max(0,from-50);albums();});if(to<choices.size())button("Siguientes",()->{albumOffset=to;albums();});note("Se consultan hasta 500 imágenes por volumen. Si no encuentras una foto, usa el selector del sistema o envíala por QR.");button("Volver",()->{if(!album.isEmpty()){album="";albumOffset=0;albums();}else{page="main";render();}});});});
 }
 public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==42){albums();if(grants.length==0||grants[0]!=PackageManager.PERMISSION_GRANTED)message("Permiso no concedido. Puedes usar Recibir del celular.");}}
 private void importOne(Uri uri,String name){message("Importando…");task(()->{File temp=null;String text;try{temp=store.copyUri(uri);store.importImage(temp,name);text="Imagen importada. Puedes elegirla en Mi biblioteca.";}catch(Exception e){text=e.getMessage();}finally{if(temp!=null)temp.delete();}final String result=text;ui.post(()->message(result));});}
 private void updateDaily(){message("Consultando Wikimedia…");final int token=generation;online=new WallpaperOnline();final WallpaperOnline client=online;task(()->{String text;try{text=client.update(this,true);}catch(Exception e){text="Se conserva el paisaje anterior: "+e.getMessage();}final String result=text;ui.post(()->{if(foreground&&token==generation)message(result);});});}
 private void credits(){JSONObject c=WallpaperOnline.credit(this);new AlertDialog.Builder(this).setTitle("Información del fondo").setMessage(c.length()==0?"Todavía no hay un paisaje descargado":android.text.Html.fromHtml(c.optString("title")+"<br>"+c.optString("author")+"<br>"+c.optString("license")+"<br>"+c.optString("licenseUrl")+"<br>"+c.optString("source"),0)).setPositiveButton("Volver",null).show();}
 private String localAddress(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);LinkProperties links=cm.getLinkProperties(cm.getActiveNetwork());if(links!=null)for(LinkAddress address:links.getLinkAddresses())if(address.getAddress() instanceof Inet4Address&&!address.getAddress().isLoopbackAddress())return address.getAddress().getHostAddress();return null;}
 private void receive(){stopReceiver("");page="receive";base("Recibir del celular");note("1. Conecta el celular a la misma red que el TV.\n2. Escanea el QR y selecciona tus fotos en el navegador.\n3. Vuelve a Fondos para elegir su uso.\n\nMáximo 20 MB por foto, 50 imágenes y 100 MB optimizados. Esta pantalla debe permanecer abierta. La sesión dura 15 minutos.");String address=localAddress();if(address==null){message("No hay conexión de red local. Conecta el TV a Wi-Fi o Ethernet.");button("Volver",()->{page="main";render();});return;}
  final int token=generation;task(()->{PhotoReceiver incoming=null;try{incoming=new PhotoReceiver(this,text->ui.post(()->{if(foreground&&page.equals("receive")&&token==generation)message(text);}));final PhotoReceiver session=incoming;String url="http://"+address+":"+session.port()+session.path();QrCode qr=QrCode.encodeText(url,QrCode.Ecc.MEDIUM);int scale=5,border=4,size=(qr.size+border*2)*scale;Bitmap image=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);image.eraseColor(Color.WHITE);for(int y=0;y<qr.size;y++)for(int x=0;x<qr.size;x++)if(qr.getModule(x,y))for(int yy=0;yy<scale;yy++)for(int xx=0;xx<scale;xx++)image.setPixel((x+border)*scale+xx,(y+border)*scale+yy,Color.BLACK);
   ui.post(()->{if(!foreground||token!=generation){session.close();image.recycle();return;}receiver=session;receiverUrl=url;preview=image;ImageView view=new ImageView(this);previewView=view;view.setImageBitmap(image);view.setScaleType(ImageView.ScaleType.FIT_CENTER);list.addView(view,new LinearLayout.LayoutParams(-1,dp(235)));note("También puedes abrir esta dirección:\n"+url);button("Cerrar recepción y volver",()->{stopReceiver("");page="main";render();});getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);session.start();ui.postDelayed(expire,15*60000L);ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);networkCallback=new ConnectivityManager.NetworkCallback(){public void onLost(Network n){ui.post(()->stopReceiver("La red se desconectó. Abre otra recepción al volver a conectarte."));}};cm.registerDefaultNetworkCallback(networkCallback);message("Recepción abierta durante 15 minutos");});
  }catch(Exception e){if(incoming!=null)incoming.close();ui.post(()->{message("No se pudo abrir la recepción: "+e.getMessage());button("Volver",()->{page="main";render();});});}});
 }
 private void stopReceiver(String text){if(receiver!=null){receiver.close();receiver=null;}receiverUrl="";ui.removeCallbacks(expire);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(networkCallback!=null){try{((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).unregisterNetworkCallback(networkCallback);}catch(RuntimeException ignored){}networkCallback=null;}if(!text.isEmpty())message(text);}
 public void onBackPressed(){if(page.equals("main")){finish();return;}stopReceiver("");album="";albumOffset=0;page="main";render();}
 private static int[] dimensions(File file){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(file.getAbsolutePath(),o);return new int[]{o.outWidth,o.outHeight};}
 static String inspect()throws Exception {JSONObject out=new JSONObject();WallpaperActivity a=current;out.put("visible",a!=null&&a.foreground);if(a!=null){out.put("dailyAvailable",WallpaperOnline.file(a)!=null);out.put("dailyDate",a.prefs.getString("wallpaper_daily_date",""));out.put("page",a.page);out.put("mode",a.prefs.getString("wallpaper_mode","original"));out.put("quality",a.prefs.getString("wallpaper_quality","light"));out.put("receiverRunning",a.receiver!=null&&a.receiver.running());out.put("receiverUrl",a.receiverUrl);JSONArray photos=new JSONArray();for(WallpaperStore.Photo p:a.store.photos())photos.put(new JSONObject().put("id",p.id).put("name",p.name).put("bytes",p.file.length()).put("width",dimensions(p.file)[0]).put("height",dimensions(p.file)[1]));out.put("photos",photos);int temporary=0;File[] cache=a.getCacheDir().listFiles();if(cache!=null)for(File f:cache)if(f.getName().startsWith("incoming-"))temporary++;out.put("incomingTemporaryFiles",temporary);out.put("status",a.status==null?"":a.status.getText());}return out.toString();}
 static String shellAction(String action){WallpaperActivity a=current;if(a==null||!a.foreground)return "NOT_VISIBLE";if(action.equals("receive"))a.receive();else if(action.equals("close"))a.onBackPressed();else if(action.equals("library")){a.page="library";a.render();}else if(action.equals("albums")){a.page="albums";a.albums();}else if(action.equals("update"))a.updateDaily();else if(action.startsWith("mode:")){String mode=action.substring(5);if(!Arrays.asList("original","photo","slideshow","daily").contains(mode))return "INVALID";a.applyMode(mode);}else if(action.startsWith("select:")){String id=action.substring(7);if(a.store.find(id)==null)return "INVALID";a.prefs.edit().putString("wallpaper_photo",id).putString("wallpaper_mode","photo").apply();a.main();}else if(action.startsWith("preview:")){a.photoId=action.substring(8);a.page="photo";a.photo();}else if(action.equals("quality")){String q=a.prefs.getString("wallpaper_quality","light").equals("light")?"balanced":"light";a.prefs.edit().putString("wallpaper_quality",q).apply();a.main();}else if(action.startsWith("move:")){a.move(Integer.parseInt(action.substring(5)));}else if(action.startsWith("remove:")){String id=action.substring(7);a.task(()->{try{a.store.remove(id);a.ui.post(()->{a.page="library";a.render();});}catch(Exception e){a.ui.post(()->a.message(e.getMessage()));}});}else if(action.equals("expire"))a.expire.run();else return "NOT_FOUND";return "OK";}
}
